service.method:

			DELETE FROM SIFLH 
			 WHERE 1 = 1 
			   AND MODULE = ${MODULE}
               AND HOUSE_CODE = ${HOUSE_CODE}


			SELECT COUNT(*)
			  FROM SIFLH
			 WHERE 1 = 1
			   AND MODULE = ${MODULE}
               AND HOUSE_CODE = ${HOUSE_CODE}


			UPDATE  SIFLH
			   SET  LAST_EXECUTE_DATE = ${current.DATE}
				   ,LAST_EXECUTE_TIME = ${current.TIME}
				   ,MODULE_NAME       = ${MODULE_NAME}
				   ,RFC_NAME          = ${RFC_NAME}
				   ,DEL_FLAG          = ${DEL_FLAG}
				   ,PROCESS_ID        = ${PROCESS_ID}
				   ,METHOD_NAME       = ${METHOD_NAME}
                   ,HOUSE_CODE        = ${HOUSE_CODE}
			 WHERE  MODULE            = ${MODULE}


			UPDATE  SIFLH
			   SET  LAST_EXECUTE_DATE = ${current.DATE}
				   ,LAST_EXECUTE_TIME = ${current.TIME}
			 WHERE  PROCESS_ID        = ${PROCESS_ID}
             AND    HOUSE_CODE        = ${HOUSE_CODE}
